"""Visualize the SAM1 box-prompt masks generated by ``segment_sam1_box.py``.

For every ``masks/<stem>.npy`` produced by the segmenter this script:

* Renders a 3-panel JPG saved to ``images/<stem>.jpg``:
    [original | original + GT bbox | original + GT bbox + mask overlay]
* Computes per-object mIoU (mask vs its GT bbox rectangle) and aggregates
  them into a per-image mean.
* Builds per-class contact-sheet grids with a tile per object.  Tiles whose
  parent image falls below ``--miou_threshold`` get a red border and a red
  ``mIoU=0.42`` text so they are obvious in the grid.
* Emits CSV/JSON/MD reports so you can grep for the worst stems.

Usage:
    python src/data_prep_SAM1/sam_masks_full/visualize_results.py --clean
    python src/data_prep_SAM1/sam_masks_full/visualize_results.py \\
        --miou_threshold 0.6 --mask_alpha 0.5 --workers 8
"""
from __future__ import annotations

import argparse
import csv
import multiprocessing as mp
import shutil
import time
import xml.etree.ElementTree as ET
from collections import defaultdict
from pathlib import Path
from typing import Iterable

import cv2
import numpy as np

PROJECT_ROOT = Path(__file__).resolve().parents[3]
RAW_XML_DIR = PROJECT_ROOT / "data" / "raw" / "ECUSTFD" / "Annotations"
IMG_DIR = PROJECT_ROOT / "data" / "raw" / "ECUSTFD" / "JPEGImages"
PATCHED_XML_DIR = PROJECT_ROOT / "data" / "processed" / "bbox_full" / "Annotations_patched"
OUT_DIR = PROJECT_ROOT / "data" / "processed" / "sam_masks_full"
MASKS_DIR = OUT_DIR / "masks"
IMAGE_OUT_DIR = OUT_DIR / "images"
GRID_OUT_DIR = OUT_DIR / "grids"

CLASS_ORDER = [
    "apple", "banana", "bread", "bun", "coin", "doughnut", "egg",
    "fired_dough_twist", "grape", "lemon", "litchi", "mango", "mooncake",
    "orange", "peach", "pear", "plum", "qiwi", "sachima", "tomato",
]
CLASS_COLORS_RGB = [
    (255, 82, 82), (255, 213, 79), (211, 153, 102), (188, 170, 154),
    (180, 180, 180), (244, 67, 54), (255, 255, 255), (255, 152, 0),
    (156, 39, 176), (255, 235, 59), (233, 30, 99), (255, 193, 7),
    (121, 85, 72), (255, 112, 67), (255, 171, 145), (156, 204, 101),
    (103, 58, 183), (139, 195, 74), (175, 122, 197), (229, 57, 53),
]
CLASS_COLORS_BGR = [tuple(reversed(c)) for c in CLASS_COLORS_RGB]

DEFAULT_MIOU_THRESHOLD = 0.5
PANEL_GAP = 8
PANEL_HEADER = 36

# Poor result highlight (BGR for cv2).
RED_BOX = (0, 0, 255)


# ---------------------------------------------------------------------------
# Helpers - input
# ---------------------------------------------------------------------------

def find_image(stem: str) -> Path | None:
    for ext in (".JPG", ".jpg", ".jpeg", ".png"):
        if (IMG_DIR / f"{stem}{ext}").exists():
            return IMG_DIR / f"{stem}{ext}"
    return None


def load_mask(stem: str) -> dict | None:
    path = MASKS_DIR / f"{stem}.npy"
    if not path.exists():
        return None
    return np.load(str(path), allow_pickle=True).item()


def parse_voc_objects(xml_path: Path) -> list[tuple[str, tuple[int, int, int, int]]]:
    if not xml_path.exists():
        return []
    try:
        root = ET.parse(str(xml_path)).getroot()
    except ET.ParseError:
        return []
    out: list[tuple[str, tuple[int, int, int, int]]] = []
    for obj in root.findall("object"):
        name_node = obj.find("name")
        box_node = obj.find("bndbox")
        if name_node is None or box_node is None or not name_node.text:
            continue
        try:
            coords = tuple(int(float(box_node.find(k).text))
                           for k in ("xmin", "ymin", "xmax", "ymax"))
        except (AttributeError, ValueError, TypeError):
            continue
        out.append((name_node.text.strip(), coords))
    return out


def resolve_xml_path(stem: str) -> Path:
    """Patched XML takes priority; falls back to raw XML."""
    patched = PATCHED_XML_DIR / f"{stem}.xml"
    if patched.exists():
        return patched
    return RAW_XML_DIR / f"{stem}.xml"


def clamp_box(box: tuple[int, int, int, int], width: int, height: int) -> tuple[int, int, int, int]:
    x1, y1, x2, y2 = box
    return (
        max(0, min(width - 1, x1)),
        max(0, min(height - 1, y1)),
        max(0, min(width - 1, x2)),
        max(0, min(height - 1, y2)),
    )


def class_color_rgb(class_name: str) -> tuple[int, int, int]:
    try:
        idx = CLASS_ORDER.index(class_name)
    except ValueError:
        idx = len(CLASS_ORDER)
    return CLASS_COLORS_RGB[idx % len(CLASS_COLORS_RGB)]


def class_color_bgr(class_name: str) -> tuple[int, int, int]:
    return tuple(reversed(class_color_rgb(class_name)))


# ---------------------------------------------------------------------------
# mIoU + per-image stats
# ---------------------------------------------------------------------------

def mask_iou_vs_bbox(mask: np.ndarray, bbox_voc: tuple[int, int, int, int]) -> tuple[float, float, int, int]:
    """mask vs the GT bbox rectangle (1-indexed VOC bbox)."""
    H, W = mask.shape
    x1, y1, x2, y2 = bbox_voc
    box = np.zeros((H, W), dtype=bool)
    box[max(0, y1):min(H, y2 + 1), max(0, x1):min(W, x2 + 1)] = True
    inter = float(np.logical_and(mask, box).sum())
    union = float(np.logical_or(mask, box).sum())
    miou = inter / max(1.0, union)
    cov = inter / float(max(1, box.sum()))
    return miou, cov, int(inter), int(mask.sum())


def compute_image_stats(stem: str, payload: dict) -> dict | None:
    objects = payload.get("objects", [])
    if not objects:
        return None
    miou_per = []
    cov_per = []
    fill_per = []
    classes = []
    for obj in objects:
        mask = obj.get("mask")
        bbox = tuple(obj["bbox_voc"])
        if mask is None or not isinstance(mask, np.ndarray):
            continue
        miou, cov, _inter, mask_area = mask_iou_vs_bbox(mask, bbox)
        miou_per.append(miou)
        cov_per.append(cov)
        # fill = mask area / bbox area (1 means mask covers all of bbox)
        bw = max(1, bbox[2] - bbox[0] + 1)
        bh = max(1, bbox[3] - bbox[1] + 1)
        bbox_area = bw * bh
        fill_per.append(mask_area / max(1, bbox_area))
        classes.append(obj["class"])
    if not miou_per:
        return None
    return {
        "stem": stem,
        "source": payload.get("source", ""),
        "num_objects": len(miou_per),
        "mean_miou": float(np.mean(miou_per)),
        "min_miou": float(np.min(miou_per)),
        "max_miou": float(np.max(miou_per)),
        "mean_coverage": float(np.mean(cov_per)),
        "mean_fill": float(np.mean(fill_per)),
        "classes": ";".join(classes),
    }


# ---------------------------------------------------------------------------
# Rendering
# ---------------------------------------------------------------------------

def overlay_mask(image_rgb: np.ndarray, mask: np.ndarray, color_rgb: tuple[int, int, int], alpha: float = 0.5) -> np.ndarray:
    out = image_rgb.copy()
    if not mask.any():
        return out
    color_f = np.array(color_rgb, dtype=np.float32)
    overlay = out[mask].astype(np.float32)
    out[mask] = (alpha * color_f + (1.0 - alpha) * overlay).astype(np.uint8)
    # Draw mask contour for sharpness (cv2 expects an int color tuple).
    contours, _ = cv2.findContours(mask.astype(np.uint8) * 255,
                                   cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)
    if contours:
        cv2.drawContours(out, contours, -1, tuple(int(c) for c in color_rgb), 2, lineType=cv2.LINE_AA)
    return out


def render_three_panel(image_bgr: np.ndarray, gt_objects: list[tuple[str, tuple[int, int, int, int]]],
                       pred_objects: list[dict], mask_alpha: float, header_text: str) -> np.ndarray | None:
    """Build [orig | GT bbox | GT bbox + mask] panel (cv2 BGR)."""
    if image_bgr is None:
        return None
    H, W = image_bgr.shape[:2]

    panel_orig = image_bgr.copy()
    panel_gt = image_bgr.copy()
    panel_mask = image_bgr.copy()

    # Draw GT bbox for each real object.
    for class_name, box in gt_objects:
        x1, y1, x2, y2 = clamp_box(box, W, H)
        color_bgr = class_color_bgr(class_name)
        cv2.rectangle(panel_gt, (x1, y1), (x2, y2), color_bgr, 2, cv2.LINE_AA)
        cv2.rectangle(panel_mask, (x1, y1), (x2, y2), color_bgr, 2, cv2.LINE_AA)
        # label
        label = class_name
        (tw, th), baseline = cv2.getTextSize(label, cv2.FONT_HERSHEY_SIMPLEX, 0.45, 1)
        cv2.rectangle(panel_gt, (x1, max(0, y1 - th - baseline - 4)),
                      (x1 + tw + 6, max(0, y1)), color_bgr, -1, cv2.LINE_AA)
        cv2.putText(panel_gt, label, (x1 + 3, max(0, y1 - baseline - 2)),
                    cv2.FONT_HERSHEY_SIMPLEX, 0.45, (0, 0, 0), 1, cv2.LINE_AA)

    # Draw mask overlay on panel_mask using pred_objects.
    panel_mask_rgb = cv2.cvtColor(panel_mask, cv2.COLOR_BGR2RGB)
    for pred in pred_objects:
        m = pred.get("mask")
        cls = pred.get("class", "")
        if m is None or not isinstance(m, np.ndarray) or not m.any():
            continue
        rgb = class_color_rgb(cls)
        colored = overlay_mask(panel_mask_rgb, m.astype(bool), rgb, mask_alpha)
        panel_mask_rgb = colored
    panel_mask_bgr = cv2.cvtColor(panel_mask_rgb, cv2.COLOR_RGB2BGR)

    # Compose three panels horizontally.
    total_w = 3 * W + 2 * PANEL_GAP
    canvas = np.full((H + PANEL_HEADER, total_w, 3), 24, dtype=np.uint8)
    canvas[PANEL_HEADER:, 0:W] = panel_orig
    canvas[PANEL_HEADER:, W + PANEL_GAP:2 * W + PANEL_GAP] = panel_gt
    canvas[PANEL_HEADER:, 2 * W + 2 * PANEL_GAP:3 * W + 2 * PANEL_GAP] = panel_mask_bgr

    # Header text on top.
    cv2.putText(canvas, header_text, (10, 24),
                cv2.FONT_HERSHEY_SIMPLEX, 0.6, (255, 255, 255), 1, cv2.LINE_AA)

    # Panel labels above each panel.
    cv2.putText(canvas, "original", (10, PANEL_HEADER - 6),
                cv2.FONT_HERSHEY_SIMPLEX, 0.55, (200, 200, 200), 1, cv2.LINE_AA)
    cv2.putText(canvas, "GT bbox", (W + PANEL_GAP + 10, PANEL_HEADER - 6),
                cv2.FONT_HERSHEY_SIMPLEX, 0.55, (200, 200, 200), 1, cv2.LINE_AA)
    cv2.putText(canvas, "GT bbox + mask overlay", (2 * W + 2 * PANEL_GAP + 10, PANEL_HEADER - 6),
                cv2.FONT_HERSHEY_SIMPLEX, 0.55, (200, 200, 200), 1, cv2.LINE_AA)
    return canvas


def render_image_job(args: tuple[str, float]) -> tuple[str, dict | None, str | None]:
    stem, mask_alpha = args
    try:
        payload = load_mask(stem)
        if payload is None:
            return (stem, None, "no_mask")
        gt_objects = parse_voc_objects(resolve_xml_path(stem))
        img_path = find_image(stem)
        if img_path is None:
            return (stem, None, "no_image")
        image = cv2.imread(str(img_path), cv2.IMREAD_COLOR)
        if image is None:
            return (stem, None, "read_fail")
        stats = compute_image_stats(stem, payload)
        miou_text = f"{stats['mean_miou']:.2f}" if stats else "n/a"
        header = f"{stem}  mean_mIoU={miou_text}  src={payload.get('source','?')}  n={stats['num_objects'] if stats else 0}"
        canvas = render_three_panel(image, gt_objects, payload.get("objects", []),
                                    mask_alpha=mask_alpha, header_text=header)
        if canvas is None:
            return (stem, None, "render_fail")
        out_path = IMAGE_OUT_DIR / f"{stem}.jpg"
        cv2.imwrite(str(out_path), canvas, [cv2.IMWRITE_JPEG_QUALITY, 92])
        return (stem, stats, None)
    except Exception as exc:  # noqa: BLE001
        import traceback
        tb = traceback.format_exc()
        return (stem, None, f"error:{type(exc).__name__}: {tb.splitlines()[-2] if tb else 'unknown'}")


def render_tile(args: tuple[str, int, int, int, str, float, float, float]) -> tuple[np.ndarray | None, bool]:
    """Render a tile showing the highlighted object for one (stem, obj_idx) entry.

    The last element of ``args`` is the configured mIoU threshold so the worker
    process can flag poor tiles without relying on a global.
    """
    stem, obj_idx, tile_size, tile_number, class_label, mask_alpha, mean_miou, threshold = args
    img_path = find_image(stem)
    if img_path is None:
        return None, False
    image = cv2.imread(str(img_path), cv2.IMREAD_COLOR)
    if image is None:
        return None, False
    payload = load_mask(stem)
    if payload is None:
        return None, False
    objects = payload.get("objects", [])
    if obj_idx >= len(objects):
        return None, False
    pred = objects[obj_idx]
    bbox_voc = tuple(pred["bbox_voc"])
    H, W = image.shape[:2]
    x1, y1, x2, y2 = clamp_box(bbox_voc, W, H)
    bw = x2 - x1 + 1
    bh = y2 - y1 + 1
    # Pad the crop a little so the tile has breathing room.
    pad = int(0.10 * max(bw, bh))
    cx1 = max(0, x1 - pad)
    cy1 = max(0, y1 - pad)
    cx2 = min(W, x2 + pad + 1)
    cy2 = min(H, y2 + pad + 1)
    crop = image[cy1:cy2, cx1:cx2]
    if crop.size == 0:
        return None, False

    # Draw GT bbox on the crop (using original VOC coords adjusted by cx1/cy1).
    color_bgr = class_color_bgr(pred["class"])
    cv2.rectangle(crop, (x1 - cx1, y1 - cy1), (x2 - cx1, y2 - cy1), color_bgr, 3, cv2.LINE_AA)
    label = f"{pred['class']}"
    (tw, th), baseline = cv2.getTextSize(label, cv2.FONT_HERSHEY_SIMPLEX, 0.55, 1)
    cv2.rectangle(crop, (max(0, x1 - cx1), max(0, y1 - cy1 - th - baseline - 4)),
                  (max(0, x1 - cx1) + tw + 6, max(0, y1 - cy1)), color_bgr, -1, cv2.LINE_AA)
    cv2.putText(crop, label, (max(0, x1 - cx1) + 3, max(0, y1 - cy1) - baseline - 2),
                cv2.FONT_HERSHEY_SIMPLEX, 0.55, (0, 0, 0), 1, cv2.LINE_AA)

    # Overlay mask only inside the original bbox region (we're working on the crop).
    mask_full = pred.get("mask")
    if mask_full is not None and isinstance(mask_full, np.ndarray):
        sub_mask = mask_full[cy1:cy2, cx1:cx2].astype(bool)
        if sub_mask.any():
            crop_rgb = cv2.cvtColor(crop, cv2.COLOR_BGR2RGB)
            rgb = class_color_rgb(pred["class"])
            color_arr = np.array(rgb, dtype=np.float32)
            overlay = crop_rgb[sub_mask].astype(np.float32)
            crop_rgb[sub_mask] = (mask_alpha * color_arr + (1.0 - mask_alpha) * overlay).astype(np.uint8)
            contours, _ = cv2.findContours(sub_mask.astype(np.uint8) * 255,
                                           cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)
            if contours:
                cv2.drawContours(crop_rgb, contours, -1, rgb, 2, lineType=cv2.LINE_AA)
            crop = cv2.cvtColor(crop_rgb, cv2.COLOR_RGB2BGR)

    # Resize crop to tile_size (square, padded with dark border).
    tile = np.zeros((tile_size, tile_size, 3), dtype=np.uint8)
    ch, cw = crop.shape[:2]
    scale = min(tile_size / ch, tile_size / cw)
    new_w = max(1, int(cw * scale))
    new_h = max(1, int(ch * scale))
    resized = cv2.resize(crop, (new_w, new_h), interpolation=cv2.INTER_AREA)
    px = (tile_size - new_w) // 2
    py = (tile_size - new_h) // 2
    tile[py:py + new_h, px:px + new_w] = resized

    # Badge: tile number on top-right.
    badge = f"#{tile_number:04d}"
    cv2.rectangle(tile, (tile_size - 90, 0), (tile_size, 24), (30, 30, 220), -1, cv2.LINE_AA)
    cv2.putText(tile, badge, (tile_size - 84, 17), cv2.FONT_HERSHEY_SIMPLEX, 0.5, (255, 255, 255), 1, cv2.LINE_AA)

    # Stem caption at bottom-left.
    cv2.rectangle(tile, (0, tile_size - 22),
                  (min(tile_size - 1, 8 * len(stem) + 12), tile_size - 1), (0, 0, 0), -1, cv2.LINE_AA)
    cv2.putText(tile, stem, (4, tile_size - 6),
                cv2.FONT_HERSHEY_SIMPLEX, 0.40, (255, 255, 255), 1, cv2.LINE_AA)

    # Highlight poor-mIoU images with red border + red mIoU text.
    is_poor = mean_miou < threshold
    if is_poor:
        cv2.rectangle(tile, (0, 0), (tile_size - 1, tile_size - 1), RED_BOX, 4, cv2.LINE_AA)
        cv2.rectangle(tile, (4, 4), (130, 28), RED_BOX, -1, cv2.LINE_AA)
        cv2.putText(tile, f"mIoU={mean_miou:.2f}", (8, 22),
                    cv2.FONT_HERSHEY_SIMPLEX, 0.55, (255, 255, 255), 2, cv2.LINE_AA)
    return tile, True


# Globals used by worker processes (currently none - all thresholds are passed
# explicitly as part of the ``render_tile`` argument tuple so workers do not
# need to read mutable globals).


# ---------------------------------------------------------------------------
# Main
# ---------------------------------------------------------------------------

def ordered_classes(classes: Iterable[str]) -> list[str]:
    available = set(classes)
    known = [c for c in CLASS_ORDER if c in available]
    return known + sorted(available - set(CLASS_ORDER))


def make_grid(tiles: list[np.ndarray], tile_size: int, cols: int, page: int, total_pages: int, class_name: str) -> np.ndarray:
    rows = max(1, (len(tiles) + cols - 1) // cols)
    header_height = 34
    grid = np.full((header_height + rows * tile_size, cols * tile_size, 3), 32, dtype=np.uint8)
    cv2.putText(grid, f"{class_name}  page {page}/{total_pages}",
                (8, 22), cv2.FONT_HERSHEY_SIMPLEX, 0.6, (255, 255, 255), 1, cv2.LINE_AA)
    for idx, tile in enumerate(tiles):
        if tile is None:
            tile = np.full((tile_size, tile_size, 3), (60, 0, 0), dtype=np.uint8)
            cv2.putText(tile, "MASK MISSING", (10, tile_size // 2),
                        cv2.FONT_HERSHEY_SIMPLEX, 0.55, (255, 255, 255), 1, cv2.LINE_AA)
        r, c = divmod(idx, cols)
        y = header_height + r * tile_size
        x = c * tile_size
        grid[y:y + tile_size, x:x + tile_size] = tile
    return grid


def write_csv(path: Path, fieldnames: list[str], rows: list[dict]) -> None:
    with path.open("w", newline="", encoding="utf-8") as fh:
        writer = csv.DictWriter(fh, fieldnames=fieldnames)
        writer.writeheader()
        writer.writerows(rows)


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--per_page", type=int, default=80)
    parser.add_argument("--cols", type=int, default=8)
    parser.add_argument("--tile", type=int, default=240)
    parser.add_argument("--workers", type=int, default=max(1, min(8, mp.cpu_count())))
    parser.add_argument("--miou_threshold", type=float, default=DEFAULT_MIOU_THRESHOLD)
    parser.add_argument("--mask_alpha", type=float, default=0.5)
    parser.add_argument("--clean", action="store_true",
                        help="wipe images/, grids/, and CSV outputs under sam_masks_full/ "
                             "(preserves masks/ and run.log)")
    args = parser.parse_args()

    if args.per_page < 1 or args.cols < 1 or args.tile < 32 or args.workers < 1:
        parser.error("per_page, cols must be positive; tile >= 32; workers >= 1")
    if not (0.0 < args.mask_alpha < 1.0):
        parser.error("--mask_alpha must be in (0,1)")

    if not MASKS_DIR.exists():
        print(f"[fatal] masks dir missing: {MASKS_DIR}", flush=True)
        return 2

    # Optional clean: drop images, grids, CSVs, README - keep masks and logs.
    if args.clean and OUT_DIR.exists():
        # Static artifacts we never want to wipe.
        preserve = {"masks", "run.log", "README.md"}
        # Per-run logs from the notebook's run_script_step helper live in
        # `logs/run_<timestamp>.log`. Preserve that directory too so
        # re-running this script does not delete the log it is currently
        # writing to.
        for entry in OUT_DIR.iterdir():
            if entry.name in preserve:
                continue
            if entry.name == "logs":
                continue
            if entry.is_dir():
                shutil.rmtree(entry)
            else:
                entry.unlink(missing_ok=True)
    IMAGE_OUT_DIR.mkdir(parents=True, exist_ok=True)
    GRID_OUT_DIR.mkdir(parents=True, exist_ok=True)

    # Enumerate stems from masks/.
    stems = sorted(p.stem for p in MASKS_DIR.glob("*.npy"))
    print(f"[scan] masks: {len(stems)}  workers: {args.workers}  miou_thr: {args.miou_threshold}", flush=True)

    # ------- Phase 1: render 3-panel JPGs and compute per-image stats -------
    t0 = time.time()
    jobs = [(s, args.mask_alpha) for s in stems]
    stats_by_stem: dict[str, dict] = {}

    with mp.Pool(processes=args.workers) as pool:
        for idx, (stem, stats, err) in enumerate(pool.imap_unordered(render_image_job, jobs), 1):
            if err is not None:
                print(f"  [err] {stem}: {err}", flush=True)
            elif stats is not None:
                stats_by_stem[stem] = stats
            if idx % 100 == 0 or idx == len(stems):
                elapsed = time.time() - t0
                rate = idx / max(elapsed, 0.001)
                print(f"  render {idx}/{len(stems)}  elapsed={elapsed:.1f}s  rate={rate:.2f}/s",
                      flush=True)

    # Persist per-image stats (sorted by stem for stability).
    stats_rows = sorted(stats_by_stem.values(), key=lambda r: r["stem"])
    write_csv(
        OUT_DIR / "_per_image_stats.csv",
        ["stem", "source", "num_objects", "mean_miou", "min_miou", "max_miou",
         "mean_coverage", "mean_fill", "classes"],
        stats_rows,
    )

    # Classify poor results.
    poor_rows = [r for r in stats_rows if r["mean_miou"] < args.miou_threshold]
    poor_rows.sort(key=lambda r: r["mean_miou"])
    write_csv(
        OUT_DIR / "_poor_miou_report.csv",
        ["stem", "source", "num_objects", "mean_miou", "min_miou", "max_miou",
         "mean_coverage", "mean_fill", "classes"],
        poor_rows,
    )
    print(f"[scan] poor (mIoU<{args.miou_threshold}): {len(poor_rows)} / {len(stats_rows)}", flush=True)

    # ------- Phase 2: per-class tile grids -----------------------------------
    buckets: dict[str, list[tuple[str, int]]] = defaultdict(list)
    for stem in stems:
        payload = load_mask(stem)
        if payload is None:
            continue
        for obj_idx, obj in enumerate(payload.get("objects", [])):
            buckets[obj.get("class", "?")].append((stem, obj_idx))

    class_names = ordered_classes(buckets)
    counts_rows = []
    index_rows: list[dict] = []
    global_tile = 0

    for class_index, class_name in enumerate(class_names):
        items = sorted(buckets[class_name])
        total_pages = (len(items) + args.per_page - 1) // args.per_page
        counts_rows.append({"class": class_name, "n_objects": len(items), "n_pages": total_pages})
        print(f"  {class_name}: {len(items)} objects ({total_pages} pages)", flush=True)
        for page in range(1, total_pages + 1):
            chunk = items[(page - 1) * args.per_page:page * args.per_page]
            # Pre-filter the chunk: drop entries whose mask file is missing.
            filtered: list[tuple[int, str, int]] = []
            for page_local, (stem, obj_idx) in enumerate(chunk, start=1):
                payload = load_mask(stem)
                if payload is None or obj_idx >= len(payload.get("objects", [])):
                    continue
                filtered.append((page_local, stem, obj_idx))
            if not filtered:
                continue

            page_global_start = global_tile + 1
            tile_jobs: list[tuple] = []
            job_meta: list[tuple[int, str, int]] = []  # parallel list: (page_local, stem, obj_idx)
            for page_local, stem, obj_idx in filtered:
                payload = load_mask(stem)
                obj = payload["objects"][obj_idx]
                stats = stats_by_stem.get(stem)
                mean_miou = stats["mean_miou"] if stats else 1.0
                global_tile += 1
                tile_jobs.append((stem, obj_idx, args.tile, global_tile,
                                  f"{class_name}[{obj_idx}]", args.mask_alpha,
                                  float(mean_miou), args.miou_threshold))
                job_meta.append((page_local, stem, obj_idx))

            with mp.Pool(processes=args.workers) as pool:
                tiles_rendered = pool.map(render_tile, tile_jobs)
            tiles = [t for t, ok in tiles_rendered]
            grid = make_grid(tiles, args.tile, args.cols, page, total_pages, class_name)
            grid_path = GRID_OUT_DIR / f"{class_index:02d}_{class_name}_p{page:02d}_of_{total_pages:02d}.png"
            cv2.imwrite(str(grid_path), grid, [cv2.IMWRITE_PNG_COMPRESSION, 3])
            for (page_local, stem, obj_idx), (_, ok) in zip(job_meta, tiles_rendered):
                payload = load_mask(stem)
                obj = payload["objects"][obj_idx]
                stats = stats_by_stem.get(stem)
                mean_miou = stats["mean_miou"] if stats else 1.0
                index_rows.append({
                    "tile_global": page_global_start + (page_local - 1),
                    "class": obj.get("class", ""),
                    "page": page,
                    "page_local": page_local,
                    "stem": stem,
                    "obj_idx": obj_idx,
                    "bbox_xmin": obj["bbox_voc"][0],
                    "bbox_ymin": obj["bbox_voc"][1],
                    "bbox_xmax": obj["bbox_voc"][2],
                    "bbox_ymax": obj["bbox_voc"][3],
                    "image": str(Path("images") / f"{stem}.jpg"),
                    "rendered": bool(ok),
                    "mean_miou": float(mean_miou),
                    "poor": bool(mean_miou < args.miou_threshold),
                })
            print(f"    saved {grid_path.name} ({len(tiles)} tiles)", flush=True)

    write_csv(
        OUT_DIR / "_index.csv",
        ["tile_global", "class", "page", "page_local", "stem", "obj_idx",
         "bbox_xmin", "bbox_ymin", "bbox_xmax", "bbox_ymax",
         "image", "rendered", "mean_miou", "poor"],
        index_rows,
    )
    write_csv(OUT_DIR / "_per_class_counts.csv", ["class", "n_objects", "n_pages"], counts_rows)

    # ------- Markdown report -------------------------------------------------
    md = OUT_DIR / "_segmentation_report.md"
    lines = [
        "# SAM1 box-prompt segmentation report",
        "",
        f"- Total images with masks: **{len(stats_rows)}**",
        f"- Total annotated objects: **{sum(r['num_objects'] for r in stats_rows)}**",
        f"- Classes covered: **{len(class_names)}** (incl. coin)",
        f"- mIoU threshold for poor flag: **{args.miou_threshold:.2f}**",
        f"- Mean (over images) of per-image mean mIoU: "
        f"**{float(np.mean([r['mean_miou'] for r in stats_rows]) if stats_rows else 0):.3f}**",
        f"- Images flagged poor (mean mIoU < {args.miou_threshold:.2f}): "
        f"**{len(poor_rows)} / {len(stats_rows)}**",
        "",
        "## Distribution of per-image mean mIoU",
        "",
    ]
    if stats_rows:
        miou_vals = np.array([r["mean_miou"] for r in stats_rows])
        bins = [0.0, 0.2, 0.4, 0.6, 0.8, 1.01]
        hist, edges = np.histogram(miou_vals, bins=bins)
        for i, count in enumerate(hist):
            lines.append(
                f"- `[{edges[i]:.2f}, {edges[i + 1]:.2f})`: **{count}** images"
            )
    lines += [
        "",
        "## Top 20 worst mIoU images",
        "",
        "| stem | source | mean mIoU | min mIoU | coverage | n |",
        "|---|---|---|---|---|---|",
    ]
    for r in poor_rows[:20]:
        lines.append(
            f"| {r['stem']} | {r['source']} | {r['mean_miou']:.3f} | "
            f"{r['min_miou']:.3f} | {r['mean_coverage']:.3f} | {r['num_objects']} |"
        )
    md.write_text("\n".join(lines) + "\n", encoding="utf-8")

    # Auto README
    readme = OUT_DIR / "README.txt"
    readme.write_text(
        "SAM1 (vit_b) box-prompt segmentation visualization for the full ECUSTFD dataset.\n\n"
        "Source masks: data/processed/sam_masks_full/masks/<stem>.npy (each contains\n"
        "every annotated object: food + coin).\n\n"
        "Output:\n"
        "  images/                    - 3-panel JPG (orig | GT bbox | GT bbox + mask) per image.\n"
        "  grids/                     - per-class contact sheets; poor mIoU tiles have a red border + label.\n"
        "  _index.csv                 - tile-global index (each object tile + its mean mIoU).\n"
        "  _per_image_stats.csv       - mIoU / coverage / fill per image, sorted by stem.\n"
        "  _per_class_counts.csv      - object counts per class.\n"
        "  _poor_miou_report.csv      - images with mean mIoU < --miou_threshold, sorted worst-first.\n"
        f"  _segmentation_report.md    - human-readable summary. mIoU threshold = {args.miou_threshold:.2f}.\n",
        encoding="utf-8",
    )

    # ------- Console summary -------------------------------------------------
    total_t = time.time() - t0
    print(f"\n[done] rendered images: {len(stats_rows)}/{len(stems)}  grids: {len(index_rows)} tiles", flush=True)
    print(f"[done] poor (mIoU<{args.miou_threshold}): {len(poor_rows)} -> {OUT_DIR / '_poor_miou_report.csv'}", flush=True)
    print(f"[done] output: {OUT_DIR}  total elapsed: {total_t:.1f}s", flush=True)
    return 0


if __name__ == "__main__":
    mp.freeze_support()
    raise SystemExit(main())
